-- ═══════════════════════════════════════════════════════════════════════════
--  0159 — Khalidiyah's forms, the tables (the first 12 of 23; 0160 the rest)
--
--  GENERATED by supabase/khalidiyah/gen_schema.py from workbook.py (the one
--  reading of Khaldia_2_reviewed.xlsx) and catalogue.py. Do not edit.
--
--  ── ONE TABLE PER FORM ──
--
--  The reviewed workbook has 24 forms. FORM-03 holds one field (F010, the
--  attempt ID) and the reviewer's note says to merge it into FORM-04, so the
--  two are one table, khld_partner_contact, and F010 is its reference,
--  issued by the database (KHLD-ATT-NN). Every other form is its own table,
--  whose comment names it. Every column is a field of the form; which one is
--  catalogue.FIELDS (Field ID -> kind and column), from which the screens,
--  the locale files and this file are all generated.
--
--  ── WHAT IS NOT A COLUMN ──
--
--  A multi-select is a khld_<table>_option row per tick (question_code = the
--  Field ID in lower case, guard_khld_option). F118 and F131 (partners at a
--  meeting, on an activity) are junction rows. A file upload is an attachment
--  whose field_code is the Field ID (0158). The person fields of FORM-12,
--  FORM-15 and FORM-17 -- name, sex, date of birth, identifier, phone -- are
--  `person`, one person one row (hard rule 6), through khld_ensure_person
--  (0161); the record keeps the ID TYPE the form chose (F144 / F151 / F156),
--  which is how the shared definitions tell a refugee ("ID type = UNHCR
--  registration"). F069 and F111 are the name of the person picked, shown.
--  F012 and F159 ("(Auto gen.) date/time") default to the moment of saving.
--
--  ── THE SHEET'S VALIDATION COLUMN ──
--
--  CHECK constraints: the 0-100 percentages, F040 + F041 = 100 and F042 +
--  F043 = 100 (the reviewer's note on those fields), Jordanian% + Syrian%
--  <= 100, completed <= agreed, action days within the campaign's dates, the
--  1-5 scales, the minimums (>= 1, >= 0), dates in order, one contributor,
--  one occasion. The Dependency column is khld_field_rule (0158).
--
--  ── WHO WRITES WHAT ──
--
--  FORM-12 is also a public form: the municipality's owner decided on 26
--  September 2026 that volunteers register themselves. khld_volunteer
--  carries application_status: a staff entry is approved when saved, a
--  public one arrives 'submitted' (khld_register_volunteer, 0161) and counts
--  only once staff approve it -- SO3-0's denominator is "all registered
--  volunteers", and an unreviewed public form would let anyone move it.
--  F060 "if no then disqualified" is a CHECK: a volunteer is a resident. No
--  guardian block: the reviewed FORM-12 asks for none and the owner chose to
--  follow the sheet (06_OPEN_QUESTIONS.md). The three questionnaires
--  (FORM-19, -20, -24) are written by any staff role, enumerators included
--  (is_staff); every other table by coordinators and data entry (can_write).
--
--  ── UNIQUENESS ──
--
--  Entities are unique GLOBALLY, deleted rows included -- a partner per name,
--  a volunteer per person -- so re-entering a deleted one is a restore,
--  never a second row. Things someone took part in are unique while live: a
--  request per person per session, an application per person per market,
--  one attendance a day.
--
--  ── EVERY TABLE ──
--
--  municipality_id (default my_municipality(); the composite (id,
--  municipality_id) key; every link to another Khalidiyah table is a
--  COMPOSITE foreign key and the only key on that pair, so PostgREST sees one
--  relationship and never answers 300), the standard block, client_uuid. The
--  standard triggers, RLS, the junctions' DELETE policy and an index on
--  every foreign key are added in 0160, over all the tables at once.
-- ═══════════════════════════════════════════════════════════════════════════

create table public.khld_focal_point (
  id uuid primary key default gen_random_uuid(),
  municipality_id uuid not null references public.municipality(id) default public.my_municipality(),
  focal_point_name text not null,
  phone text not null,
  assigned_on date not null,
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_focal_point_id_municipality_key unique (id, municipality_id)
);
comment on table public.khld_focal_point is 'FORM-01 -- Responsible Officer (Focal point). 0159.';

create table public.khld_partner (
  id uuid primary key default gen_random_uuid(),
  municipality_id uuid not null references public.municipality(id) default public.my_municipality(),
  name text not null,
  phone text not null,
  partner_type_id uuid not null references public.ref_khld_partner_type(id),
  expected_contribution text,
  contact_position text,
  email text,
  partner_category_id uuid not null references public.ref_khld_partner_category(id),
  partner_category_other text,
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_partner_id_municipality_key unique (id, municipality_id)
);
create unique index khld_partner_name_key on public.khld_partner (municipality_id, lower(btrim(name)));
comment on table public.khld_partner is 'FORM-02 -- List of potential partners (Partners). 0159.';
create trigger trg_khld_partner_other before insert or update on public.khld_partner for each row execute function public.guard_rmth_other('partner_category_id:ref_khld_partner_category:partner_category_other');

create table public.khld_partner_contact (
  id uuid primary key default gen_random_uuid(),
