  notes text,
  evaluation_id uuid references public.ref_khld_attempt_evaluation(id),
  partnership_confirmed boolean,
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_partner_contact_id_municipality_key unique (id, municipality_id),
  constraint khld_partner_contact_reference_key unique (municipality_id, reference),
  constraint khld_partner_contact_partner_id_fkey foreign key (partner_id, municipality_id) references public.khld_partner(id, municipality_id)
);
comment on table public.khld_partner_contact is 'FORM-03 + FORM-04 -- Reach out to partners (Partner outreach). 0159.';
create trigger trg_khld_partner_contact_reference before insert on public.khld_partner_contact for each row execute function public.khld_assign_reference('ATT', '2');
create trigger trg_khld_partner_contact_rules before insert or update on public.khld_partner_contact for each row execute function public.guard_khld_rules();

