create trigger trg_khld_meeting_other before insert or update on public.khld_meeting for each row execute function public.guard_rmth_other('meeting_type_id:ref_khld_meeting_type:meeting_type_other');

create table public.khld_rehab_report (
  id uuid primary key default gen_random_uuid(),
  municipality_id uuid not null references public.municipality(id) default public.my_municipality(),
  reference text,
  completion_pct numeric(5,2) not null,
  report_date date not null,
  accomplished text not null,
  agreed_total int not null,
  completed_count int not null,
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_rehab_report_id_municipality_key unique (id, municipality_id),
  constraint khld_rehab_report_reference_key unique (municipality_id, reference),
  constraint khld_rehab_report_completion_pct_0_100 check (completion_pct between 0 and 100),
  constraint khld_rehab_report_agreed_total_min check (agreed_total >= 1),
  constraint khld_rehab_report_completed_count_min check (completed_count >= 0),
  constraint khld_rehab_report_completed_within_agreed check (completed_count <= agreed_total)
);
comment on table public.khld_rehab_report is 'FORM-06 -- Checklist (Rehabilitation progress). 0159.';
create trigger trg_khld_rehab_report_reference before insert on public.khld_rehab_report for each row execute function public.khld_assign_reference('REH', '2', 'report_date');

create table public.khld_campaign (
  id uuid primary key default gen_random_uuid(),
  municipality_id uuid not null references public.municipality(id) default public.my_municipality(),
  reference text,
  campaign_name text not null,
  start_date date not null,
  end_date date not null,
  applications_open date not null,
  applications_close date not null,
  description text not null,
  has_sponsor boolean not null,
  sponsor_name text,
  status_id uuid not null references public.ref_khld_event_status(id),
  action_days int,
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_campaign_id_municipality_key unique (id, municipality_id),
  constraint khld_campaign_reference_key unique (municipality_id, reference),
  constraint khld_campaign_action_days_min check (action_days >= 1),
  constraint khld_campaign_dates_in_order check (end_date >= start_date),
  constraint khld_campaign_window_in_order check (applications_close >= applications_open),
  constraint khld_campaign_action_days_within_dates check (action_days is null or action_days <= (end_date - start_date + 1))
);
comment on table public.khld_campaign is 'FORM-07 -- Volunteer Campaigns (Volunteer campaigns). 0159.';
create trigger trg_khld_campaign_reference before insert on public.khld_campaign for each row execute function public.khld_assign_reference('VC', '2', 'start_date');
create trigger trg_khld_campaign_rules before insert or update on public.khld_campaign for each row execute function public.guard_khld_rules();

