create table public.khld_activity_attendance (
  id uuid primary key default gen_random_uuid(),
  municipality_id uuid not null references public.municipality(id) default public.my_municipality(),
  report_date date not null,
  activity_id uuid not null,
  total_participants int not null,
  pct_children numeric(5,2) not null,
  pct_adults numeric(5,2) not null,
  pct_male numeric(5,2) not null,
  pct_female numeric(5,2) not null,
  pct_disability numeric(5,2) not null,
  social_media_links text,
  counting_method_id uuid not null references public.ref_khld_counting_method(id),
  pct_youth numeric(5,2) not null,
  pct_jordanian numeric(5,2) not null,
  pct_syrian numeric(5,2) not null,
  observed_interaction_id uuid not null references public.ref_khld_observed_interaction(id),
  client_uuid uuid unique,
  created_at timestamptz not null default now(),
