  created_by uuid references auth.users(id) default auth.uid(),
  deleted_at timestamptz,
  constraint khld_activity_attendance_id_municipality_key unique (id, municipality_id),
  constraint khld_activity_attendance_activity_id_fkey foreign key (activity_id, municipality_id) references public.khld_activity(id, municipality_id),
  constraint khld_activity_attendance_total_participants_min check (total_participants >= 0),
  constraint khld_activity_attendance_pct_children_0_100 check (pct_children between 0 and 100),
  constraint khld_activity_attendance_pct_adults_0_100 check (pct_adults between 0 and 100),
  constraint khld_activity_attendance_pct_male_0_100 check (pct_male between 0 and 100),
  constraint khld_activity_attendance_pct_female_0_100 check (pct_female between 0 and 100),
  constraint khld_activity_attendance_pct_disability_0_100 check (pct_disability between 0 and 100),
  constraint khld_activity_attendance_pct_youth_0_100 check (pct_youth between 0 and 100),
  constraint khld_activity_attendance_pct_jordanian_0_100 check (pct_jordanian between 0 and 100),
  constraint khld_activity_attendance_pct_syrian_0_100 check (pct_syrian between 0 and 100),
  constraint khld_activity_attendance_age_split_is_100 check (pct_children + pct_adults = 100),
  constraint khld_activity_attendance_sex_split_is_100 check (pct_male + pct_female = 100),
  constraint khld_activity_attendance_nationality_within_100 check (pct_jordanian + pct_syrian <= 100)
);
